{"command": "# We have dynamic symbols. Let's use them to resolve the addresses.
# Extract all function symbols sorted by address
aarch64-linux-gnu-nm -D --defined-only -C /tmp/symbols/libmonosgen-2.0.so | sort > /tmp/symbols/sorted_syms.txt

# Now resolve each address by finding the nearest preceding symbol
ADDRS="0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40"
for addr in $ADDRS; do
  # Find the last symbol whose address is <= the target
  result=$(awk -v target="$addr" '
    BEGIN { best_addr=""; best_name="" }
    {
      sym_addr = "0x" $1
      if (sym_addr <= target) { best_addr = $1; best_name = $3 }
    }
    END { if (best_addr != "") printf "0x%s %s +0x%x\n", best_addr, best_name, strtonum(target) - strtonum("0x" best_addr) }
  ' /tmp/symbols/sorted_syms.txt)
  echo "$addr -> $result"
done", "description": "Resolve addresses to symbols"}

