arguments.command:
# Those are in the SGen worker thread, not interp - let me re-check
# The nm approach is unreliable for label symbols. Let me use the full symtab properly.
python3 << 'PYEOF'
import subprocess

result = subprocess.run(
    ['aarch64-linux-gnu-nm', '--defined-only', '/tmp/symbols/dbg/libmonosgen-2.0.so.dbg'],
    capture_output=True, text=True
)

symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split(None, 2)
    if len(parts) >= 3:
        addr = int(parts[0], 16)
        sym_type = parts[1]
        name = parts[2]
        if sym_type in ('T', 't'):
            symbols.append((addr, name))

symbols.sort(key=lambda x: x[0])

for target in [0x2f4b20, 0x2f4c84]:
    best = None
    for addr, name in symbols:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f"0x{target:08x} -> {best[1]}+0x{offset:x} (func at 0x{best[0]:x})")
PYEOF

