# Let me check the .text range and see what function calls would land there
# These are Cortex-A53 843419 linker-generated veneer/thunks placed in data sections
# The actual code they redirect to should be resolvable from the linker symbols

# Let me look at the __CortexA53843419 symbols near those addresses
aarch64-linux-gnu-nm /tmp/symbols/dbg/libmonosgen-2.0.so.dbg | grep CortexA53 | sort | awk '{
  a = strtonum("0x" $1)
  if (a >= 0x2f4b00 && a <= 0x2f4d00) print
}'", "description": "Find Cortex thunk symbols"}

