# These addresses are in .data.rel.ro (runtime-relocated data), not code.
# Let's find what data symbols are at or near these addresses
python3 << 'PYEOF'
import subprocess

result = subprocess.run(
    ['aarch64-linux-gnu-nm', '--defined-only', '/tmp/symbols/dbg/libmonosgen-2.0.so.dbg'],
    capture_output=True, text=True
)

symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split(None, 2)
    if len(parts) >= 3:
        addr = int(parts[0], 16)
        symbols.append((addr, parts[1], parts[2]))

symbols.sort(key=lambda x: x[0])

for target in [0x2f4b20, 0x2f4c84]:
    best = None
    for addr, stype, name in symbols:
        if addr <= target:
            best = (addr, stype, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f"0x{target:x} -> {best[2]} (type={best[1]}) +0x{offset:x} (at 0x{best[0]:x})")

    # Also show a few symbols around it
    print("  Nearby symbols:")
    for addr, stype, name in symbols:
        if abs(addr - target) < 0x80:
            print(f"    0x{addr:x} {stype} {name}")
    print()
PYEOF

